<?php
$page = max(1, (int) ($pagination['page'] ?? 1));
$pages = max(1, (int) ($pagination['pages'] ?? 1));
$page = min($page, $pages);
$start = max(1, $page - 2);
$end = min($pages, $page + 2);
$base = $filters ?? [];
?>
<?php if ($pages > 1): ?><nav class="ri-pagination pharmacy-pagination" aria-label="Medicine availability pages"><span class="ri-pagination-summary">Page <?= $page ?> of <?= $pages ?> · <?= (int) ($pagination['total'] ?? 0) ?> records</span><div class="ri-pagination-controls"><a class="ri-page-link <?= $page <= 1 ? 'is-disabled' : '' ?>" href="<?= $page > 1 ? base_url('pharmacy/inventory?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $page - 1]))) : '#' ?>" aria-label="Previous page" <?= $page <= 1 ? 'aria-disabled="true" tabindex="-1"' : '' ?>><i class="bi bi-chevron-left" aria-hidden="true"></i><span class="sr-only">Previous</span></a><?php if ($start > 1): ?><a class="ri-page-link" href="<?= base_url('pharmacy/inventory?' . http_build_query(array_merge($base, ['view' => $view, 'page' => 1]))) ?>">1</a><?php if ($start > 2): ?><span class="ri-page-ellipsis">…</span><?php endif; ?><?php endif; ?><?php for ($number = $start; $number <= $end; $number++): ?><a class="ri-page-link <?= $number === $page ? 'is-active' : '' ?>" href="<?= base_url('pharmacy/inventory?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $number]))) ?>" <?= $number === $page ? 'aria-current="page"' : '' ?>><?= $number ?></a><?php endfor; ?><?php if ($end < $pages): ?><?php if ($end < $pages - 1): ?><span class="ri-page-ellipsis">…</span><?php endif; ?><a class="ri-page-link" href="<?= base_url('pharmacy/inventory?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $pages]))) ?>"><?= $pages ?></a><?php endif; ?><a class="ri-page-link <?= $page >= $pages ? 'is-disabled' : '' ?>" href="<?= $page < $pages ? base_url('pharmacy/inventory?' . http_build_query(array_merge($base, ['view' => $view, 'page' => $page + 1]))) : '#' ?>" aria-label="Next page" <?= $page >= $pages ? 'aria-disabled="true" tabindex="-1"' : '' ?>><i class="bi bi-chevron-right" aria-hidden="true"></i><span class="sr-only">Next</span></a></div></nav><?php endif; ?>
